"""Paired truly autogenerated 14M GPTNeoX answers with fixed-sha Green."""
import time,torch
from .protocol import PROBES,MAX_NEW_TOKENS
from .neox_adapter import NeoXAdapter

@torch.inference_mode()
def compare_neox(model,tok,policy):
    model.eval();policy.eval()
    adapter=NeoXAdapter(model)
    records=[]
    try:
        for q in PROBES:
            prompt=tok(q,return_tensors="pt")["input_ids"]
            def generate():
                start=time.perf_counter()
                outputs=model.generate(
                    input_ids=prompt,
                    max_new_tokens=MAX_NEW_TOKENS,
                    do_sample=False,
                    use_cache=True,
                    pad_token_id=tok.eos_token_id)
                elapsed=time.perf_counter()-start
                new=outputs[0,prompt.shape[1]:]
                return {"text":tok.decode(new,skip_special_tokens=True),
                        "token_ids":new.tolist(),"seconds":elapsed,
                        "new_tokens":len(new)}
            adapter.neutral()
            base=generate()
            start=time.perf_counter()
            physical=adapter.set_question(policy,q)
            cost=time.perf_counter()-start
            controlled=generate()
            records.append({"prompt":q,"base":base,"green":controlled,
                            "controller_seconds":cost,
                            "full_green_seconds":cost+controlled["seconds"],
                            "nonzero_token_impact":base["token_ids"]!=controlled["token_ids"],
                            "operator_control":physical})
    finally:
        adapter.restore()
    return {"real_neox_model":"EleutherAI/pythia-14m",
            "source_dtype":"FP32, NOT under 0.7bpp for this host",
            "exactly_same_frozen_neural_controller":True,
            "role_based_adapter_changed_own_weights":False,
            "produced":records,
            "different_token_sequences":sum(x["nonzero_token_impact"] for x in records),
            "total_prompts":len(records),
            "wall_original_seconds":sum(x["base"]["seconds"] for x in records),
            "wall_steered_plus_controller_seconds":sum(x["full_green_seconds"] for x in records)}
